$ErrorActionPreference='Stop'; $vswhere='C:\Program Files (x86)\Microsoft Visual Studio\Installer\vswhere.exe'; $install=& $vswhere -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath; if(!$install){throw 'x64 MSVC build tools missing.'}; $out=Join-Path $PSScriptRoot 'dist\owned-integrated-gate'; New-Item -Force -ItemType Directory $out|Out-Null; $n=Join-Path $PSScriptRoot native; $meta=Join-Path $PSScriptRoot 'tools\build-owned-cross-ehcont-object.mjs'; $cmd=('ml64.exe /nologo /W3 /WX /c /Fo"{0}\gate_raw.obj" "{1}\owned_cross_gate.asm" && node "{2}" "{0}\gate_raw.obj" "{0}\gate.obj" OwnedCrossGate && ml64.exe /nologo /W3 /WX /c /Fo"{0}\step_raw.obj" "{1}\owned_integrated_step.asm" && node "{2}" "{0}\step_raw.obj" "{0}\step.obj" OwnedIntegratedResume OwnedIntegratedFaultPark && cl.exe /nologo /std:c++17 /W4 /WX /EHsc /O2 /MD /Gy /guard:cf /guard:ehcont /c /Fo"{0}\integrated.obj" "{1}\owned_integrated_gate.cpp" && cl.exe /nologo /std:c++17 /W4 /WX /EHsc /O2 /MD /Gy /guard:cf /guard:ehcont /c /Fo"{0}\control.obj" "{1}\inprocess_gate_control.cpp" && cl.exe /nologo /std:c++17 /W4 /WX /EHsc /O2 /MD /Gy /guard:cf /guard:ehcont /c /Fo"{0}\host.obj" "{1}\owned_integrated_gate_host.cpp" && link.exe /nologo /OUT:"{0}\TF3OwnedIntegratedGate.exe" "{0}\integrated.obj" "{0}\control.obj" "{0}\host.obj" "{0}\gate.obj" "{0}\step.obj" synchronization.lib /DYNAMICBASE /NXCOMPAT /GUARD:CF /GUARD:EHCONT /CETCOMPAT' -f $out,$n,$meta); & cmd.exe /d /s /c ('call "{0}\VC\Auxiliary\Build\vcvars64.bat" && {1}' -f $install,$cmd); if($LASTEXITCODE){throw 'Owned integrated gate build failed'}; if($RunSmokeTest){& "$out\TF3OwnedIntegratedGate.exe";if($LASTEXITCODE){throw 'Owned integrated gate failed'}}
